python3 -c "
import json
with open('/app/resources/treasury_bulletin_1947_02.json', 'r') as f:
    data = json.load(f)

# Look at the structure
def find_key(obj, target, depth=0):
    if depth > 10:
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            if target.lower() in k.lower():
                print(f'Found key: {k}')
            find_key(v, target, depth+1)
    elif isinstance(obj, list) and len(obj) > 0:
        find_key(obj[0], target, depth+1)

# Let's just look at keys at top level
print('Top level keys:')
for k in data.keys():
    print(f'  {k}')
"

python3 -c "
import json
with open('/app/resources/treasury_bulletin_1947_02.json', 'r') as f:
    data = json.load(f)

doc = data['document']

# Let's check for tables in all elements
tables_found = []
for page_num, page in enumerate(doc['pages']):
    if 'elements' in page:
        for elem in page['elements']:
            if elem.get('type') == 'table':
                tables_found.append((page_num, elem.get('rows', [])))

print(f'Found {len(tables_found)} tables')
# Show first few rows of first table
if tables_found:
    first_table = tables_found[0]
    print(f'First table on page {first_table[0]}:')
    for row in first_table[1][:10]:
        print(row)
"

